function decode(encoded, first) {
  // arr[k] is first XOR-ed with every encoded value before position k; recompute it from scratch each time.
  const result = [];
  for (let k = 0; k <= encoded.length; k++) {
    let value = first;
    for (let j = 0; j < k; j++) value = value ^ encoded[j];
    result.push(value);
  }
  return result;
}

